def _template_synthetic_dataset(config: dict, seed: int = 42):
    """R4 synthetic stand-in (only used when allow_synthetic_data=True).
    input (1, 96, 96, 96) (float); target kind 'class'.
    Evidence: explicit:monai(in_channels,spatial)=(1, 96, 96, 96); classes:monai.out_channels=2"""
    input_shape = tuple(config.get("synthetic_input_shape", (1, 96, 96, 96)))
    n = int(config.get("synthetic_num_samples", 18))
    g = torch.Generator().manual_seed(seed)
    x = torch.randn((n, *input_shape), generator=g)
    y = torch.randint(0, 2, (n,), generator=g)
    return torch.utils.data.TensorDataset(x, y)

